import sys

def parse(s):
    p = s.split('.')
    if len(p) != 4:
        return None
    r = []
    for x in p:
        if not x or len(x) > 3:
            return None
        for c in x:
            if c < '0' or c > '9':
                return None
        if len(x) > 1 and x[0] == '0':
            return None
        v = int(x)
        if v > 255:
            return None
        r.append(v)
    return tuple(r)

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    cnt = {}
    for i in range(n):
        t = parse(data[1 + 3 * i])
        if t is not None:
            cnt[t] = cnt.get(t, 0) + 1
    if not cnt:
        print('NONE')
        return
    best = min(cnt, key=lambda k: (-cnt[k], k))
    print('.'.join(map(str, best)), cnt[best])

main()

